'use client';

import { useState, useEffect, memo } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { Printer, Eye } from 'lucide-react';
import { printOrder } from '../../services/printService';
import { kdsToast } from '../toast/KDSToast';
import { useKDSStore, KDSState } from '../../store/kdsStore';
import { useKDSSound } from '../sound/useKDSSound';
import { getSLAState } from '../../utils/slaUtils';
import { OrderDetailModal } from '../modals/OrderDetailModal';

interface Props {
    orderId: string;
}

export const OrderTicket = memo(({ orderId }: Props) => {
    const {
        order,
        enable_station_routing,
        selectedStationId,
        category_station_map,
        allow_item_station_override,
        item_station_map,
        master_screen_view_mode
    } = useKDSStore(useShallow((state: KDSState) => ({
        order: state.orders[orderId],
        enable_station_routing: state.enable_station_routing,
        selectedStationId: state.selectedStationId,
        category_station_map: state.category_station_map,
        allow_item_station_override: state.allow_item_station_override,
        item_station_map: state.item_station_map,
        master_screen_view_mode: state.master_screen_view_mode
    })));

    const [isProcessing, setIsProcessing] = useState(false);
    const [isDetailOpen, setIsDetailOpen] = useState(false);
    const { advanceStage, toggleItemCompletion } = useKDSStore.getState();
    const { playSound } = useKDSSound();

    const [timer, setTimer] = useState("00:00:00");

    useEffect(() => {
        if (!order) return;
        const interval = setInterval(() => {
            const diff = Date.now() - new Date(order.createdAt).getTime();
            const h = Math.floor(diff / 3600000).toString().padStart(2, '0');
            const m = Math.floor((diff % 3600000) / 60000).toString().padStart(2, '0');
            const s = Math.floor((diff % 60000) / 1000).toString().padStart(2, '0');
            setTimer(`${h}:${m}:${s}`);
        }, 1000);
        return () => clearInterval(interval);
    }, [order?.createdAt]);

    if (!order) return null;

    const visibleItems = order.items.filter(item => {
        if (!enable_station_routing || selectedStationId === 'ALL') return true;
        if (master_screen_view_mode === 'FULL_ORDER') return true;
        const catStation = (item.categoryId && category_station_map[item.categoryId]) || 'kitchen';
        const itemStationId = (allow_item_station_override && item_station_map[item.name]) || catStation;
        return itemStationId === selectedStationId;
    });

    if (visibleItems.length === 0) return null;

    const slaState = getSLAState(order.createdAt, order.prepTimeMinutes);

    const getStatusInfo = () => {
        if (slaState === 'OVERDUE') return { label: 'DELAYED', color: 'bg-[#E74C3C]' };
        if (order.stage === 'NEW') return { label: 'QUEUE', color: 'bg-[#374151]' };
        return { label: 'COOKING', color: 'bg-[#E67E22]' };
    };

    const status = getStatusInfo();

    const handleAdvance = (e: React.MouseEvent) => {
        e.stopPropagation();
        setIsProcessing(true);
        advanceStage(orderId);
        playSound('BUMP_ORDER');
        setTimeout(() => setIsProcessing(false), 500);
    };

    const handlePrint = async (e: React.MouseEvent) => {
        e.stopPropagation();
        const state = useKDSStore.getState();
        const result = await printOrder(orderId, (id) => state.orders[id], {
            station_print_mode: state.station_print_mode,
            selectedStationId: state.selectedStationId,
            enable_station_routing: state.enable_station_routing,
            category_station_map: state.category_station_map,
            item_station_map: state.item_station_map,
            allow_item_station_override: state.allow_item_station_override
        });
        if (result.status === 'SUCCESS') kdsToast.success(result.message);
    };

    return (
        <>
            <div
                className={`kds-ticket bg-white flex flex-col border border-gray-200 shadow-sm relative h-full animate-ticket transition-all hover:border-gray-400 group cursor-default ${isProcessing ? 'opacity-50' : ''}`}
                onClick={() => setIsDetailOpen(true)}
            >
                {/* HEADER */}
                <div className="p-4 flex justify-between items-start border-b border-gray-100">
                    <div className="flex flex-col">
                        <div className="flex items-center gap-1.5">
                            <span className="text-[14px] font-black text-gray-900 tracking-tight">#{order.orderNumber}</span>
                            <span className="text-[12px] font-bold text-gray-800 tracking-tight truncate max-w-[100px]">{order.customerName || 'Guest'}</span>
                        </div>
                        <span className="text-[10px] font-bold text-gray-400 mt-0.5 uppercase tracking-tighter">
                            {order.fulfillment_type.replace('_', ' ')}
                        </span>
                    </div>
                    <div className="flex flex-col items-end">
                        <span className="text-[10px] font-black text-gray-900 mb-1">
                            Due {new Date(new Date(order.createdAt).getTime() + order.prepTimeMinutes * 60000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                        <div className="flex gap-1">
                            <span className={`px-1.5 py-0.5 rounded-sm text-[8px] font-black text-white uppercase tracking-wider ${status.color}`}>
                                {status.label}
                            </span>
                        </div>
                    </div>
                </div>

                {/* ITEMS */}
                <div className="p-4 space-y-3.5 flex-1 overflow-y-auto scrollbar-hide">
                    {visibleItems.map((item) => (
                        <div
                            key={item.id}
                            className={`flex items-start gap-3 transition-opacity ${item.isCompleted ? 'opacity-25' : ''}`}
                            onClick={(e) => {
                                e.stopPropagation();
                                toggleItemCompletion(order.id, item.id);
                            }}
                        >
                            <span className="text-[13px] font-black text-gray-900 mt-0.5">{item.quantity}</span>
                            <div className="flex-1 min-w-0">
                                <h3 className="text-[13px] font-black text-gray-900 leading-tight truncate">{item.name}</h3>
                                {(item.modifiers.length > 0 || item.variant) && (
                                    <div className="mt-1 space-y-1 pl-2.5">
                                        {[item.variant, ...item.modifiers.map(m => m.name)].filter(Boolean).map((text, idx) => (
                                            <div key={idx} className="text-[10px] text-gray-400 font-bold leading-none flex items-center gap-2">
                                                <div className="w-[3px] h-[3px] bg-gray-300 rounded-full shrink-0" />
                                                <span className="truncate">{text}</span>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>

                {/* FOOTER ACTIONS */}
                <div className="p-3 flex gap-2 border-t border-gray-100 mt-auto bg-gray-50/30">
                    <button
                        onClick={handleAdvance}
                        disabled={isProcessing}
                        className={`flex-1 h-9 rounded-sm flex items-center justify-between px-3 text-white transition-all active:scale-[0.98] ${order.stage === 'NEW' ? 'bg-[#34495E] hover:bg-[#2C3E50]' : 'bg-[#E67E22] hover:bg-[#D35400]'
                            }`}
                    >
                        <span className="text-[9px] font-black uppercase tracking-[0.15em]">
                            {order.stage === 'NEW' ? 'Start Cooking' : 'Ready'}
                        </span>
                        <span className="text-[10px] font-bold font-mono text-white/90">{timer}</span>
                    </button>
                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            handlePrint(e);
                        }}
                        className="w-9 h-9 border border-gray-200 bg-white rounded-sm flex items-center justify-center text-gray-700 hover:bg-gray-100 transition-colors shadow-sm"
                    >
                        <Printer size={15} />
                    </button>
                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            setIsDetailOpen(true);
                        }}
                        className="w-9 h-9 border border-gray-200 bg-white rounded-sm flex items-center justify-center text-gray-700 hover:bg-gray-100 transition-colors shadow-sm"
                    >
                        <Eye size={15} />
                    </button>
                </div>
            </div>

            <OrderDetailModal
                isOpen={isDetailOpen}
                onClose={() => setIsDetailOpen(false)}
                order={order}
            />
        </>
    );
});
